files.conf/nginx.conf:
worker_processes 2;

http {
  server {
    server_name www.lantern.example;
    listen 8080;
    client_max_body_size 10m;
    location / { proxy_pass http://web_pool; }
  }

  server {
    server_name api.lantern.example;
    listen 8080;
    client_max_body_size 10m;
    location / { proxy_pass http://api_pool; }
  }

  server {
    server_name admin.lantern.example;
    listen 8081;
    client_max_body_size 10m;
  }
}

